//go:build arm64

package floats

// The NEON kernel of the conjugate-reverse (conjrev.go), generated by go-asmgen
// (conjrev_arm64_gen.go) into conjrev_arm64.s: four complex numbers per step; the Go
// code finishes the last ones. NEON is the ARMv8-A baseline: no gate. No kernel keeps
// a pointer: go:noescape.
//
//go:noescape
func conjRevNEON(dst, src []float64)

func conjReverse(dst, src []float64) {
	conjRevNEON(dst, src)
	conjRevTail(dst, src, (len(dst)/2)&^3)
}
